{"content":"#!/usr/bin/env python3
"""Hermes cron catch-up: re-runs learn-pensolar + mentor-ai-daily once if
they missed their scheduled window while the host was dormant.

Idempotent: if both jobs already ran today, exit silently. One-shot by design
(call it from a cronjob with repeat=null, or trigger after restart).
"""
import json, datetime, os, sys

HERE = "/opt/data"
DB   = "cache/cron-jobs.json"          # if present — else use a simple state file
STATE = os.path.join(HERE, "cache/cron-catchup-state.json")
os.makedirs(os.path.join(HERE, "cache"), exist_ok=True)

def now_utc():
    return datetime.datetime.utcnow()

def load_state():
    if os.path.exists(STATE):
        try:
            with open(STATE) as f:
                return json.load(f)
        except Exception:
            pass
    return {"learn_run": None, "mentor_run": None}

def save_state(st):
    with open(STATE, "w") as f:
        json.dump(st, f)

def already_ran_today(key, st, offset_hours=8):
    last = st.get(key)
    if not last:
        return False
    try:
        last_dt = datetime.datetime.fromisoformat(last)
    except Exception:
        return False
    # MYT = UTC+8
    return (now_utc() - last_dt).total_seconds() < 24*3600

def mark_run(key, st):
    st[key] = now_utc().isoformat()
    save_state(st)

def run_job(name, cmd):
    import subprocess
    print(f"  running {name}: {cmd}")
    return subprocess.run(cmd, shell=True, cwd=HERE, capture_output=True, text=True, timeout=600).stdout

if __name__ == "__main__":
    st = load_state()
    ran = []

    if not already_ran_today("learn_run", st):
        out = run_job("learn-pensolar", "python3 /opt/data/knowledge/by_industry/solar_energy/pensolar/_learn_pensolar.py")
        mark_run("learn_run", st)
        ran.append("learn-pensolar")

    if not already_ran_today("mentor_run", st):
        out = run_job("mentor-ai-daily", "python3 /opt/data/knowledge/mentor/_mentor_daily.py")
        mark_run("mentor_run", st)
        ran.append("mentor-ai-daily")

    if not ran:
        print("catch-up: no missed jobs today")
    else:
        print("catch-up: re-ran " + ", ".join(ran))
","path":"/opt/data/knowledge/catchup.py"}

